import React, { useState, useEffect } from 'react';
import { usePermissions } from '../../hooks/usePermissions';
import api from '../../services/api';
import { Plus, Pencil, Trash2, Search, Shield } from 'lucide-react';
import './Users.css';

const UserList = () => {
  const { canManageUsers } = usePermissions();
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [selectedUser, setSelectedUser] = useState(null);

  if (!canManageUsers()) {
    return <div style={{ padding: '24px' }}>Access Denied</div>;
  }

  useEffect(() => {
    loadUsers();
  }, []);

  const loadUsers = async () => {
    try {
      const response = await api.get('/users/');
      setUsers(response.data);
    } catch (error) {
      console.error('Failed to load users:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (userId) => {
    if (!window.confirm('Are you sure you want to delete this user?')) return;
    try {
      await api.delete(`/users/${userId}/`);
      loadUsers();
    } catch (error) {
      alert('Failed to delete user: ' + error.response?.data?.error);
    }
  };

  const filteredUsers = users.filter(user =>
    user.username.toLowerCase().includes(search.toLowerCase()) ||
    user.email?.toLowerCase().includes(search.toLowerCase()) ||
    user.first_name?.toLowerCase().includes(search.toLowerCase()) ||
    user.last_name?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="user-management" style={{ padding: '24px' }}>
      <div className="page-header">
        <h1>User Management</h1>
        <button
          className="btn-primary"
          onClick={() => { setSelectedUser(null); setShowForm(true); }}
        >
          <Plus size={16} /> Add User
        </button>
      </div>

      <div className="search-bar">
        <Search size={18} className="search-icon" />
        <input
          type="text"
          placeholder="Search users..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      <div className="users-table">
        <table>
          <thead>
            <tr>
              <th>Username</th>
              <th>Name</th>
              <th>Email</th>
              <th>Role</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredUsers.map(user => (
              <tr key={user.id}>
                <td>{user.username}</td>
                <td>{user.first_name} {user.last_name}</td>
                <td>{user.email}</td>
                <td><span className="role-tag">{user.role || 'No Role'}</span></td>
                <td>
                  <span className={`status ${user.is_active ? 'active' : 'inactive'}`}>
                    {user.is_active ? 'Active' : 'Inactive'}
                  </span>
                </td>
                <td>
                  <button
                    className="btn-icon"
                    onClick={() => { setSelectedUser(user); setShowForm(true); }}
                  >
                    <Pencil size={16} />
                  </button>
                  <button
                    className="btn-icon danger"
                    onClick={() => handleDelete(user.id)}
                  >
                    <Trash2 size={16} />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default UserList;
